const item = $input.first().json;
const url = item.url_bases_pdf || item.url_bases || '';
if (!url) { throw new Error('No hay url_bases_pdf/url_bases para esta convocatoria: ' + JSON.stringify(item)); }
// Ya es la URL final y estable de SEACE (prod1 Alfresco o prod6 archivos-publico).
// No hace falta resolver ningun ticket ni pasar por ScraperAPI.
const mUuid = url.match(/fileCode=([a-f0-9-]{36})/i);
const mProd6 = url.match(/descargar-archivo-contrato\/(\d+)/i);
const fileCode = mUuid ? mUuid[1] : (mProd6 ? mProd6[1] : 'archivo');
const licitacion = item.nomenclatura_norm || item.licitacion;
return [{ json: { licitacion, downloadUrl: url, fileCode } }];

const resp = $input.first().json;
const headers = resp.headers || {};
const lenRaw = headers['content-length'] || headers['Content-Length'];
const bytes = lenRaw ? parseInt(lenRaw, 10) : null;
const contentType = headers['content-type'] || headers['Content-Type'] || '';
const info = $('Construir URL Directa').first().json;
return [{ json: { ...info, fileSizeBytesHead: bytes, contentType, tamanoConocido: bytes !== null } }];

const info = $('Construir URL Directa').first().json;
const input = $input.first();
if (!input.binary || Object.keys(input.binary).length === 0) {
  throw new Error(`No llego ningun binario para fileCode=${info.fileCode}. Revisa la salida real de 'Descargar Archivo (Proxy IPRoyal)'.`);
}
const binKey = Object.keys(input.binary)[0];
const bin = input.binary[binKey];
const buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
const head = buffer.subarray(0, 4);
let tipo = 'otro';
if (head[0] === 0x25 && head[1] === 0x50 && head[2] === 0x44 && head[3] === 0x46) tipo = 'pdf'; // %PDF
else if (head[0] === 0x50 && head[1] === 0x4b) {
  // PK..: un DOCX tambien es ZIP; se distingue porque lista word/document.xml en su directorio central.
  tipo = buffer.includes('word/document.xml') ? 'docx' : 'zip';
}
const fileName = info.fileCode + (tipo === 'pdf' ? '.pdf' : tipo === 'zip' ? '.zip' : tipo === 'docx' ? '.docx' : '');
if (tipo === 'pdf') { bin.mimeType = 'application/pdf'; bin.fileExtension = 'pdf'; bin.fileName = fileName; }
// El nodo Compression solo descomprime si fileExtension es 'zip', por eso el DOCX se marca como zip.
if (tipo === 'zip' || tipo === 'docx') { bin.mimeType = 'application/zip'; bin.fileExtension = 'zip'; bin.fileName = fileName + (tipo === 'docx' ? '.zip' : ''); }
return [{ json: { tipo, fileName, licitacion: info.licitacion }, binary: { data: bin } }];

const bins = $input.first().binary || {};
function parseSize(s) {
  if (!s) return 0;
  const m = String(s).match(/([\d.]+)\s*(B|kB|KB|MB|GB)/i);
  if (!m) return 0;
  const mult = { B: 1, KB: 1024, MB: 1024 ** 2, GB: 1024 ** 3 }[m[2].toUpperCase()] || 1;
  return parseFloat(m[1]) * mult;
}
function score(fullName) {
  const n = fullName.toUpperCase().replace(/_/g, ' ');
  const base = n.split('/').pop();
  const ext = base.includes('.') ? base.split('.').pop().toLowerCase() : '';
  if (!['pdf', 'docx'].includes(ext)) return -1;
  let s = 0;
  if (base.includes('BASES')) s += 100;
  if (n.includes('BASES')) s += 20;
  if (base.includes('ACTA')) s -= 80;
  if (base.includes('INTEGRADA')) s += 30;
  if (ext === 'pdf') s += 10;
  return s;
}
const candidatos = [];
for (const key of Object.keys(bins)) {
  const b = bins[key];
  // n8n separa la ruta interna del ZIP en directory + fileName; se reconstruye para puntuar carpetas 'BASES'.
  const name = (b.directory ? b.directory + '/' : '') + (b.fileName || key);
  if (name.endsWith('/')) continue;
  const sc = score(name);
  if (sc >= 0) candidatos.push({ key, name, sc, size: parseSize(b.fileSize) });
}
if (!candidatos.length) {
  throw new Error('El ZIP no contiene ningún PDF/DOCX. Archivos: ' + Object.values(bins).map(b => b.fileName).join(', '));
}
candidatos.sort((a, b) => (b.sc - a.sc) || (b.size - a.size));
const elegido = candidatos[0];
const bin = bins[elegido.key];
const ext = elegido.name.split('.').pop().toLowerCase();
const tipo = ext === 'pdf' ? 'pdf' : 'docx';
bin.fileName = elegido.name.split('/').pop();
if (tipo === 'pdf') { bin.mimeType = 'application/pdf'; bin.fileExtension = 'pdf'; }
if (tipo === 'docx') { bin.mimeType = 'application/zip'; bin.fileExtension = 'zip'; bin.fileName = bin.fileName + '.zip'; }
return [{ json: { tipo, fileName: elegido.name.split('/').pop() }, binary: { data: bin } }];

const bins = $input.first().binary || {};
// n8n guarda la ruta interna como directory='word' + fileName='document.xml'.
const rutaCompleta = (b) => ((b.directory ? b.directory + '/' : '') + (b.fileName || '')).replace(/\\/g, '/');
const key = Object.keys(bins).find(k => rutaCompleta(bins[k]).endsWith('word/document.xml'));
if (!key) { throw new Error('El DOCX no contiene word/document.xml. Archivos: ' + Object.values(bins).map(rutaCompleta).join(', ')); }
const bin = bins[key];
bin.mimeType = 'text/xml'; bin.fileExtension = 'xml'; bin.fileName = 'document.xml';
return [{ json: { fileName: $input.first().json.fileName }, binary: { data: bin } }];

const xml = $input.first().json.data || '';
let t = xml.replace(/</w:p>/g, '
').replace(/<w:tab/>/g, '	').replace(/<w:br[^>]*/>/g, '
')
  .replace(/<[^>]+>/g, '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/[ 	]+/g, ' ').replace(/
{3,}/g, '

').trim();
return [{ json: { textoDocx: t, fileName: $('Seleccionar document.xml').first().json.fileName } }];

const headers = $input.first().json.headers || {};
const uploadUrl = headers['x-goog-upload-url'] || headers['X-Goog-Upload-URL'];
if (!uploadUrl) { throw new Error('Gemini no devolvió X-Goog-Upload-URL. Headers: ' + JSON.stringify(headers)); }
return [{ json: { uploadUrl, fileSizeBytes: $('Calcular Tamaño Binario').first().json.fileSizeBytes }, binary: $('Calcular Tamaño Binario').first().binary }];

const info = $input.first().json;
const fileUri = info.file?.uri;
const mimeType = info.file?.mimeType || 'application/pdf';
if (!fileUri) { throw new Error('Gemini no devolvió file.uri: ' + JSON.stringify(info)); }
return [{ json: { fileUri, mimeType, modo: 'archivo_pdf' } }];

let itemArchivo = null;
let modo = null;
try { itemArchivo = $('Extraer File URI').first().json; modo = 'archivo_grande'; } catch (e) {}
if (!itemArchivo) {
  try { itemArchivo = $('Codificar Base64 (Inline)').first().json; modo = 'inline'; } catch (e) {}
}
let textoDocx = null;
if (!itemArchivo) {
  try { textoDocx = $('Limpiar XML a Texto').first().json.textoDocx; } catch (e) {}
}

const conv = $('Consultar Convocatoria').first().json;
const catalogo = $('Catálogo ISO Empresa').first().json.catalogoIso;
const listaCatalogo = catalogo.normas.map((n) => `- ${n.codigo}: ${n.alcance}`).join('\n');

const contexto = 'Entidad: ' + (conv.entidad || conv.entidad_convocante || 'No especificada')
  + '\nObjeto: ' + (conv.objeto || conv.objeto_contratacion || 'No especificado')
  + '\nDescripción: ' + (conv.descripcion || conv.objeto_descripcion || 'No especificada')
  + '\nCategoría: ' + (conv.categoria || 'No especificada')
  + '\nMonto Referencial: ' + (conv.monto || conv.monto_referencial || 'No especificado');

const instruccion = 'Eres un auditor senior experto en contrataciones públicas de Perú (SEACE/OSCE) y normas ISO. '
  + 'Analiza la convocatoria y el documento de bases (si está adjunto) y determina qué certificaciones ISO se mencionan '
  + 'o se exigen, y cuáles convendría tener para ganar ventaja competitiva en ESTA convocatoria. Si no hay documento legible, '
  + 'usa el contexto de la convocatoria para inferir con criterio profesional (nunca respondas "no se puede determinar").\n\n'
  + 'REGLAS:\n'
  + '1) "normas_solicitadas": SOLO las normas que las bases realmente piden o puntúan, tal como aparecen (aunque no estén en el catálogo).\n'
  + '2) "iso_recomendadas": entre 1 y 3 normas, ÚNICAMENTE del CATÁLOGO de abajo, escritas exactamente como en el catálogo. '
  + 'Prioriza primero las normas solicitadas por las bases que estén en el catálogo; luego las que más ventaja den según el objeto '
  + '(p.ej. obras/servicios con personal en campo → 45001; calidad del bien o servicio → 9001; impacto ambiental → 14001; '
  + 'integridad/anticorrupción → 37001; TI/datos → 27001). Nunca recomiendes normas fuera del catálogo.\n'
  + '3) "motivo": 1-2 líneas concretas de por qué esa norma conviene para esta convocatoria. No menciones precios.\n\n'
  + 'CATÁLOGO DE CERTIFICACIONES ISO DISPONIBLES:\n' + listaCatalogo + '\n\n'
  + 'Responde ÚNICAMENTE con un objeto JSON sin markdown con este formato:\n'
  + '{\n  "requiere_iso": "Sí (especificar ISOs)" | "Recomendado: Sí (inferido)" | "No requiere",\n'
  + '  "pide_iso": true|false,\n  "normas_solicitadas": ["ISO 9001", ...],\n'
  + '  "es_obligatorio_o_puntaje": "Obligatorio / Factor de Evaluación / No aplica / Recomendado",\n'
  + '  "iso_recomendadas": [{ "norma": "ISO 45001:2015", "motivo": "..." }],\n'
  + '  "resumen_requisitos": "Resumen de 2 líneas"\n}\n\n'
  + 'DATOS DE LA CONVOCATORIA:\n' + contexto;

const parts = [];
let archivoAnalizado;
if (modo === 'archivo_grande') {
  parts.push({ file_data: { mime_type: itemArchivo.mimeType, file_uri: itemArchivo.fileUri } });
  parts.push({ text: instruccion + '\n\n(El documento de bases va adjunto arriba en PDF, subido via File API por ser grande)' });
  archivoAnalizado = 'PDF grande (leído directo por Gemini via File API)';
} else if (modo === 'inline') {
  parts.push({ inline_data: { mime_type: itemArchivo.mimeType, data: itemArchivo.inlineBase64 } });
  parts.push({ text: instruccion + '\n\n(El documento de bases va adjunto arriba en PDF, inline)' });
  archivoAnalizado = 'PDF (leído directo por Gemini, inline)';
} else if (textoDocx) {
  parts.push({ text: instruccion + '\n\nTEXTO DE LAS BASES (extraído de un DOCX):\n\n' + textoDocx.substring(0, 150000) });
  archivoAnalizado = 'DOCX (texto extraído)';
} else {
  parts.push({ text: instruccion + '\n\n[No se pudo obtener el documento de bases. Basa tu respuesta solo en los datos de la convocatoria.]' });
  archivoAnalizado = 'Sin documento - solo metadata';
}

return [{ json: { parts, archivo_analizado: archivoAnalizado } }];

const resp = $input.first().json;
const cand = (resp.candidates || [])[0];
const responseContent = ((cand && cand.content && cand.content.parts) || [])
  .filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
if (!responseContent) {
  throw new Error('Gemini no devolvió texto (finishReason: ' + (cand && cand.finishReason) + ', promptFeedback: ' + JSON.stringify(resp.promptFeedback || null) + ')');
}
let parsed = {};
try {
  const cleanJson = responseContent.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { requiere_iso: responseContent.includes('ISO') ? 'Menciona ISO' : 'No requiere', detalle: responseContent };
}

// --- Solo se recomiendan normas del catálogo de la empresa (se valida por número, p.ej. "45001") ---
const catalogo = $('Catálogo ISO Empresa').first().json.catalogoIso;
const porNumero = Object.fromEntries(catalogo.normas.map((n) => [n.numero, n]));
const numerosDe = (txt) => (String(txt || '').match(/\d{3,5}/g) || []).filter((num) => porNumero[num]);
const solicitadas = Array.isArray(parsed.normas_solicitadas) ? parsed.normas_solicitadas : [];

const recomendadas = [];
const agregar = (num, motivo) => {
  if (porNumero[num] && !recomendadas.some((r) => r.numero === num) && recomendadas.length < 3) {
    const n = porNumero[num];
    recomendadas.push({ norma: n.codigo, numero: num, alcance: n.alcance, motivo: String(motivo || '').trim() });
  }
};
let propuestas = Array.isArray(parsed.iso_recomendadas) ? parsed.iso_recomendadas : [];
if (!propuestas.length && parsed.iso_recomendada) propuestas = [{ norma: parsed.iso_recomendada, motivo: parsed.iso_recomendada }];
for (const r of propuestas) {
  for (const num of numerosDe(typeof r === 'string' ? r : r.norma)) agregar(num, typeof r === 'string' ? '' : r.motivo);
}
// Respaldo: si la IA no dejó ninguna válida, se usan las solicitadas por las bases que estén en el catálogo, o ISO 9001.
for (const s of solicitadas) for (const num of numerosDe(s)) agregar(num, 'Las bases de la convocatoria mencionan o exigen esta norma.');
if (!recomendadas.length) agregar('9001', 'Acredita un sistema de gestión de calidad, la certificación más valorada por las entidades públicas en cualquier rubro.');
for (const r of recomendadas) {
  if (!r.motivo) r.motivo = solicitadas.some((s) => numerosDe(s).includes(r.numero))
    ? 'Las bases de la convocatoria mencionan o exigen esta norma.'
    : `Aporta ventaja competitiva al demostrar un ${r.alcance.toLowerCase()} certificado.`;
}
const numsRec = recomendadas.map((r) => r.numero).sort();
const pack = recomendadas.length > 1
  ? catalogo.packs.find((p) => p.numeros.length === numsRec.length && [...p.numeros].sort().every((n, i) => n === numsRec[i]))
  : null;

const MENSAJE_COMERCIAL = (recomendadas.length > 1 ? 'Puede obtener estas certificaciones' : 'Puede obtener esta certificación')
  + ' con nosotros. Comuníquese con nuestra área comercial o con uno de nuestros asesores para acompañarlo en el proceso.';
parsed.iso_recomendadas = recomendadas;
parsed.pack_disponible = pack ? pack.nombre : null;
parsed.mensaje_comercial = MENSAJE_COMERCIAL;
delete parsed.iso_recomendada;

const normas = solicitadas.length ? solicitadas.join(', ') : 'Ninguna';
const estado = parsed.requiere_iso || (parsed.pide_iso ? 'Sí' : 'No requiere');
const archivo = $('Preparar Prompt Gemini').first().json.archivo_analizado;
const requiereIsoCompleto = [
  `ESTADO: ${estado}`,
  `NORMAS SOLICITADAS: ${normas}`,
  `MODALIDAD: ${parsed.es_obligatorio_o_puntaje || 'No aplica'}`,
  `RESUMEN: ${parsed.resumen_requisitos || parsed.detalle || 'Sin detalle'}`,
  `ARCHIVO ANALIZADO: ${archivo}`
].join('\n');
return [{ json: { licitacion: $('Consultar Convocatoria').first().json.nomenclatura_norm, requiere_iso: requiereIsoCompleto, analisis_completo: parsed, origen: 'nuevo' } }];

function tryGet(nodeName) {
  try { return $(nodeName).first().json; } catch (e) { return null; }
}
const rnp = tryGet('Consultar RNP') || {};
const sunat = tryGet('Consultar SUNAT Ubicacion') || {};
const migoRaw = tryGet('Consultar CIIU (API MIGO)') || {};
const ruc = $('Resultado ISO').first().json.ruc;

// El nodo MIGO usa fullResponse + neverError: { statusCode, body }. Si fallo la red llega { error }.
let ciiuResp = migoRaw.body !== undefined ? migoRaw.body : migoRaw;
if (typeof ciiuResp === 'string') { try { ciiuResp = JSON.parse(ciiuResp); } catch (e) { ciiuResp = { message: ciiuResp.slice(0, 200) }; } }
ciiuResp = ciiuResp || {};
const migoStatus = migoRaw.statusCode;
let ciiuOficialError = null;
if (migoRaw.error) {
  ciiuOficialError = 'API MIGO: ' + (migoRaw.error.message || String(migoRaw.error));
} else if ((migoStatus && migoStatus >= 400) || ciiuResp.success === false) {
  ciiuOficialError = `API MIGO HTTP ${migoStatus || '?'}: ${ciiuResp.message || 'sin mensaje'}`;
  if (migoStatus === 403) ciiuOficialError += ' (plan/suscripción de API MIGO vencida: renovar en api.migo.pe)';
  if (migoStatus === 401) ciiuOficialError += ' (token de API MIGO inválido)';
}

const prov = rnp.proveedorT01 || {};
const tels = prov.telefonos || [];
const emails = prov.emails || [];
const tipReg = String(prov.lscIdTipReg || '');
const tiposRnp = [];
if (tipReg.includes('1')) tiposRnp.push('Bienes');
if (tipReg.includes('2')) tiposRnp.push('Servicios');
if (tipReg.includes('3')) tiposRnp.push('Consultoria de Obras');
if (tipReg.includes('4')) tiposRnp.push('Obras');

const especialidades = (prov.espProvT01s || []).map((e) => {
  const des = (e.desEsp || '').trim();
  const cat = (e.desCat || '').trim();
  return des ? (cat ? `${des} (Cat. ${cat})` : des) : null;
}).filter(Boolean);

const ds = sunat.datosSunat || {};

// Parsea "Principal - 4100 - CONSTRUCCION DE EDIFICIOS" / "Secundaria 1 - ..." de la API MIGO (SUNAT en vivo).
const ciius = [];
const ciiuDetalle = [];
for (const linea of (ciiuResp.actividades_economicas || [])) {
  const m = String(linea).match(/^\s*(Principal|Secundaria\s*\d*)\s*-\s*(\d{4})\s*-\s*(.+?)\s*$/i);
  if (m) {
    const [, etiqueta, cod, texto] = m;
    if (!ciius.includes(cod)) {
      ciius.push(cod);
      ciiuDetalle.push({ codigo: cod, texto, fuente: `${etiqueta} (SUNAT tiempo real)` });
    }
  }
}
const ciiuOficialOk = ciius.length > 0;
if (!ciiuOficialOk && !ciiuOficialError) ciiuOficialError = 'API MIGO respondió sin actividades económicas para este RUC';

const razonSocial = (prov.nomRzsProv || ds.razon || ciiuResp.nombre_o_razon_social || 'No identificada').trim();
// MIGO (/sunat) tambien trae estado, condicion y ubicacion: sirven de respaldo si OECE no respondio.
const txt = (v) => (v && String(v).trim() && String(v).trim() !== '-' ? String(v).trim().toUpperCase() : null);
const estadoSunat = txt(ciiuResp.estado_del_contribuyente) || txt(ds.estado) || 'No registra';
const condicionSunat = txt(ciiuResp.condicion_de_domicilio) || txt(ds.condicion) || 'No registra';
const contribuyenteOk = estadoSunat === 'ACTIVO' && condicionSunat === 'HABIDO';

// Metodo 2 (RNP / Heuristica): igual que deducir_ciius_perfil() del script Python.
// No depende de los diccionarios grandes, solo palabras clave sobre especialidad/razon social/tipo RNP.
// Sirve para cuando el CIIU oficial de SUNAT esta desactualizado o vacio.
function deducirCiiusHeuristica(razonSocial, especialidadesObras, tiposRnp) {
  const ciiusSet = new Set();
  const norm = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const rz = norm(razonSocial);
  const esps = norm(especialidadesObras.join(' '));

  if (esps.includes('vial') || esps.includes('carretera') || esps.includes('puente')) { ciiusSet.add('4210'); ciiusSet.add('7110'); }
  if (esps.includes('saneamiento') || esps.includes('agua')) { ciiusSet.add('4220'); ciiusSet.add('7110'); }
  if (esps.includes('edificac') || esps.includes('urbana')) { ciiusSet.add('4100'); ciiusSet.add('7110'); }
  if (esps.includes('electromec') || esps.includes('energ')) { ciiusSet.add('4321'); ciiusSet.add('7110'); }
  if (esps.includes('represa') || esps.includes('irrigac')) { ciiusSet.add('4290'); ciiusSet.add('7110'); }

  if (tiposRnp.includes('Consultoria de Obras')) ciiusSet.add('7110');
  if (tiposRnp.includes('Obras') && ciiusSet.size === 0) { ciiusSet.add('4100'); ciiusSet.add('4210'); }

  const kw = (arr) => arr.some((k) => rz.includes(k));
  if (kw(['constructora', 'construccion', 'edificaciones', 'obras'])) { ciiusSet.add('4100'); ciiusSet.add('4210'); }
  if (kw(['ingenieros', 'ingenieria', 'consultores', 'consultoria', 'arquitect'])) ciiusSet.add('7110');
  if (kw(['seguridad', 'vigilancia', 'resguardo', 'security'])) ciiusSet.add('8010');
  if (kw(['limpieza', 'servicios generales', 'mantenimiento'])) ciiusSet.add('8121');
  if (kw(['software', 'sistemas', 'tecnologia', 'tech', 'soluciones ti'])) { ciiusSet.add('6201'); ciiusSet.add('6202'); }
  if (kw(['farma', 'medica', 'salud', 'laboratorio', 'drogueria'])) { ciiusSet.add('4646'); ciiusSet.add('2100'); }
  if (kw(['transporte', 'logistica', 'flete', 'cargo'])) ciiusSet.add('4923');

  if (ciiusSet.size === 0) {
    if (tiposRnp.includes('Servicios')) ciiusSet.add('7020');
    else if (tiposRnp.includes('Bienes')) ciiusSet.add('4651');
  }
  return Array.from(ciiusSet);
}

const ciiusRnp = deducirCiiusHeuristica(razonSocial, especialidades, tiposRnp);
for (const cod of ciiusRnp) {
  if (!ciius.includes(cod)) {
    ciius.push(cod);
    ciiuDetalle.push({ codigo: cod, texto: 'Inferido por especialidad RNP / rubro declarado', fuente: 'RNP / Heurística' });
  }
}

const perfilProveedor = {
  ruc,
  razonSocial,
  habilitadoRnp: prov.esHabilitado ? 'SI' : 'No',
  aptoContratar: prov.esAptoContratar ? 'SI' : 'No',
  tiposRnp,
  especialidadesObras: especialidades,
  telefono: tels.length ? tels.filter(Boolean).join(' / ') : 'No registra',
  email: emails.length ? emails.filter(Boolean).join(' / ') : 'No registra',
  estadoSunat,
  condicionSunat,
  contribuyenteOk,
  departamento: txt(ds.departamento) || txt(ciiuResp.departamento) || 'NO REGISTRA',
  provincia: txt(ds.provincia) || txt(ciiuResp.provincia) || 'NO REGISTRA',
  distrito: txt(ds.distrito) || txt(ciiuResp.distrito) || 'NO REGISTRA',
  ciius,
  ciiuDetalle,
  ciiuOficialOk,
  ciiuOficialError
};

return [{ json: { perfilProveedor } }];

const resp = $input.first().json;
const cand = (resp.candidates || [])[0];
const responseContent = ((cand && cand.content && cand.content.parts) || [])
  .filter((p) => typeof p.text === 'string' && !p.thought).map((p) => p.text).join('').trim();
if (!responseContent) {
  throw new Error('Gemini no devolvió texto (finishReason: ' + (cand && cand.finishReason) + ', promptFeedback: ' + JSON.stringify(resp.promptFeedback || null) + ')');
}
let parsed = {};
try {
  parsed = JSON.parse(responseContent.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  parsed = { recomendacion: 'No determinado', resumen: responseContent };
}

// ISO recomendadas PARA ESTA EMPRESA: solo normas del catálogo (validadas por número, p.ej. "45001").
const catalogo = $('Catálogo ISO Empresa').first().json.catalogoIso;
const porNumero = Object.fromEntries(catalogo.normas.map((n) => [n.numero, n]));
const numerosDe = (txt) => (String(txt || '').match(/\d{3,5}/g) || []).filter((num) => porNumero[num]);
const iso = $('Resultado ISO').first().json;
const isoTexto = String(iso.requiere_iso || '');
const solicitadas = (iso.analisis_completo && Array.isArray(iso.analisis_completo.normas_solicitadas))
  ? iso.analisis_completo.normas_solicitadas
  : ((isoTexto.match(/NORMAS SOLICITADAS: (.*)/) || [])[1] || '').split(',').map((s) => s.trim()).filter((s) => s && s !== 'Ninguna');

const recomendadas = [];
const agregar = (num, motivo) => {
  if (porNumero[num] && !recomendadas.some((r) => r.numero === num) && recomendadas.length < 3) {
    const n = porNumero[num];
    recomendadas.push({ norma: n.codigo, numero: num, alcance: n.alcance, motivo: String(motivo || '').trim() });
  }
};
for (const s of solicitadas) for (const num of numerosDe(s)) agregar(num, 'Las bases de la convocatoria mencionan o exigen esta norma.');
for (const r of (Array.isArray(parsed.iso_recomendadas) ? parsed.iso_recomendadas : [])) {
  for (const num of numerosDe(typeof r === 'string' ? r : r.norma)) agregar(num, typeof r === 'string' ? '' : r.motivo);
}
if (!recomendadas.length) agregar('9001', 'Acredita un sistema de gestión de calidad, la certificación más valorada por las entidades públicas en cualquier rubro.');
for (const r of recomendadas) if (!r.motivo) r.motivo = `Aporta ventaja competitiva al demostrar un ${r.alcance.toLowerCase()} certificado.`;

const numsRec = recomendadas.map((r) => r.numero).sort();
const pack = recomendadas.length > 1
  ? catalogo.packs.find((p) => p.numeros.length === numsRec.length && [...p.numeros].sort().every((n, i) => n === numsRec[i]))
  : null;
const mensajeComercial = (recomendadas.length > 1 ? 'Puede obtener estas certificaciones' : 'Puede obtener esta certificación')
  + ' con nosotros. Comuníquese con nuestra área comercial o con uno de nuestros asesores para acompañarlo en el proceso.';

const brechas = Array.isArray(parsed.brechas) ? parsed.brechas : [parsed.brechas].filter(Boolean);
const recomendacionTexto = [
  `RECOMENDACIÓN: ${parsed.recomendacion || 'No determinado'}`,
  `ENCAJE: ${parsed.encaje_actividad || 'N/D'}`,
  `BRECHAS: ${brechas.join('; ') || 'Ninguna'}`,
  `RESUMEN: ${parsed.resumen || 'Sin detalle'}`,
  'ISO RECOMENDADA PARA SU EMPRESA:',
  ...recomendadas.map((r) => `- ${r.norma} (${r.alcance}): ${r.motivo}`),
  ...(pack ? [`- Disponible también como ${pack.nombre} (certificación integrada).`] : []),
  `CÓMO OBTENERLA: ${mensajeComercial}`
].join('\n');

parsed.brechas = brechas;
parsed.iso_recomendadas = recomendadas;
parsed.pack_disponible = pack ? pack.nombre : null;
parsed.mensaje_comercial = mensajeComercial;
return [{ json: { licitacion: iso.licitacion, requiere_iso: iso.requiere_iso, recomendacion_ia: recomendacionTexto, recomendacion_completa: parsed } }];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: {
