const conv = $('Consultar Convocatoria').first().json;
// El ISO depende solo de la licitación: se reutiliza. La recomendación depende del RUC, así que se recalcula.
return [{ json: { licitacion: conv.nomenclatura_norm, requiere_iso: conv.requiere_iso, analisis_completo: null, origen: 'cache' } }];

function tryGet(nodeName) {
  try { return $(nodeName).first().json; } catch (e) { return null; }
}
const webhookData = tryGet('Webhook Desbloqueo');
const testData = tryGet('Edit Fields');
const body = (webhookData && webhookData.body) || webhookData || testData || {};
// Prioridad: RUC enviado explícitamente (puede ser otra empresa) > RUC registrado en el perfil del usuario.
const rucPerfil = String((tryGet('Buscar RUC del Perfil') || {}).ruc_empresa || '').replace(/\D/g, '');
const rucRecibido = String(body.ruc ?? '').trim();
const rucExplicito = rucRecibido.replace(/\D/g, '');
const ruc = rucExplicito.length === 11 ? rucExplicito : rucPerfil;
const tieneRuc = ruc.length === 11;
const perfilId = /^[0-9a-f-]{36}$/i.test(String(body.perfil_id || '')) ? body.perfil_id : null;
// El RUC es opcional: sin RUC se entrega (y guarda) solo el análisis ISO en vez de romper el flujo.
const avisoRuc = rucRecibido && rucExplicito.length !== 11
  ? `RUC inválido ('${rucRecibido}'): debe tener 11 dígitos.` + (tieneRuc ? ' Se usó el RUC de tu perfil.' : ' Se devolvió solo el análisis ISO.')
  : null;
return [{ json: { ...$input.first().json, ruc: tieneRuc ? ruc : null, tieneRuc, avisoRuc, perfilId,
  rucOrigen: rucExplicito.length === 11 ? 'enviado' : (tieneRuc ? 'perfil' : null) } }];

